"""python -m lab.report  -> prints a table and writes docs/cases.md (generated)."""

import pathlib
import numpy as np
from .cases import run_all


def _fmt(v):
    if isinstance(v, np.ndarray):
        return np.array2string(v, precision=4, separator=", ", suppress_small=True)
    if isinstance(v, float):
        return f"{v:.6g}"
    return str(v)


def main():
    rows = run_all()
    md = [
        "# Case studies",
        "",
        "Generated by `python -m lab.report`. Each case shows the buggy and fixed output for the same input.",
        "",
    ]
    for c, b, f, ok in rows:
        md += [
            f"## {c.id}: {c.title}",
            "",
            f"* **Symptom:** {c.symptom}",
            f"* **Root cause:** {c.cause}",
            f"* **Fix:** {c.fix}",
            f"* **Property checked:** {c.property}",
            f"* **Buggy output:** `{_fmt(b)}`",
            f"* **Fixed output:** `{_fmt(f)}`",
            f"* **Bug reproduced and fix verified:** {'yes' if ok else 'NO'}",
            "",
        ]
        print(
            f"{c.id}  {'OK ' if ok else 'FAIL'}  {c.title:<42} buggy={_fmt(b)[:28]:<28} fixed={_fmt(f)[:28]}"
        )
    out = pathlib.Path(__file__).resolve().parents[1] / "docs" / "cases.md"
    out.write_text("\n".join(md), encoding="utf-8")
    return 0 if all(r[3] for r in rows) else 1


if __name__ == "__main__":
    raise SystemExit(main())
